        .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
            && owner.getPostcode().equals(existing.getPostcode())
            && !owner.getTelephone().equals(existing.getTelephone()))
        .map(Owner::getId)
        .min(Integer::compareTo)
