 */
private void stampHouseholdSize(Owner owner) {
    String householdId = owner.getHouseholdId();
    List<Owner> members = this.clinicService.findAllOwners().stream()
        .filter(existing -> householdId.equals(existing.getHouseholdId()))
        .toList();
